def handle(ev):
  if not redis.set(f'idem:{ev.id}', 1, nx=True, ex=86400):
      return                                  # duplicate delivery
  for r in resolve_recipients(ev):
      if r == ev.actor or blocked(r, ev.actor) or muted(r, ev):
          continue
      key = f'agg:{r}:{ev.object}:{ev.type}'
      g = redis.hincrby_and_push_actor(key, ev.actor, max_actors=3)  # Lua, atomic
      inbox.upsert_group(r, ev.type, ev.object, g.count, g.actors, now())
      if g.count == 1 or g.was_read:
          redis.incr(f'unread:{r}')
      if priority(ev.type) == HIGH:
          router.route_now(r, g)
      elif redis.set(f'{key}:pushwin', 1, nx=True, ex=WINDOW[ev.type]):
          scheduler.at(now() + WINDOW[ev.type], router.route, r, key)  # one push/window
